    return abs(x1 - x2) + abs(y1 - y2)

def find_nearest_checkpoint(student, checkpoints):
    left, right = 0, len(checkpoints) - 1
    while left < right:
        mid = (left + right) // 2
        if checkpoints[mid][0] >= student[0]:
            right = mid
        else:
            left = mid + 1
    candidate1 = checkpoints[left]
    candidate2 = checkpoints[left - 1] if left > 0 else None

    dist1 = manhattan_distance(student[1], student[2], candidate1[1], candidate1[2])
    dist2 = float('inf') if candidate2 is None else manhattan_distance(student[1], student[2], candidate2[1], candidate2[2])

    if dist1 <= dist2:
        return candidate1[0]
    else:
        return candidate2[0]

